// =========================================================
// QuantForge - Prepare Next Experiment
// =========================================================
// Purpose:
// 1. Prepare the next experiment after Critic
// 2. Increment experiment number
// 3. Use Critic's proposed configuration when available
// 4. If Critic ACCEPTED the current configuration,
//    deterministically create a new refinement
// 5. Never repeat an already-tested configuration
// 6. Preserve immutable research context
// =========================================================


// =========================================================
// CURRENT INPUT
// =========================================================

const current = $json;


// =========================================================
// BASIC CONTEXT
// =========================================================

const currentExperiment =
  Number(
    current.experiment || 1
  );

const maxExperiments =
  Number(
    current.max_experiments || 5
  );

const nextExperiment =
  currentExperiment + 1;


const instrument =
  current.instrument ||
  current.strategy_config?.data?.instrument;

const timeframe =
  current.timeframe ||
  current.strategy_config?.data?.timeframe;

const startingCapital =
  Number(
    current.starting_capital ??
    current.strategy_config?.capital?.starting_capital ??
    10000
  );

const researchRunId =
  current.research_run_id ||
  current.strategy_config?.research?.research_run_id;


const history =
  Array.isArray(current.history)
    ? current.history
    : [];


// =========================================================
// STOP PROTECTION
// =========================================================

if (
  nextExperiment > maxExperiments
) {

  return [{
    json: {

      ...current,

      experiment:
        nextExperiment,

      max_experiments:
        maxExperiments,

      final_experiment:
        true

    }
  }];

}


// =========================================================
// CURRENT STRATEGY CONFIG
// =========================================================

const currentConfig =
  current.strategy_config;


if (
  !currentConfig ||
  typeof currentConfig !== "object" ||
  Array.isArray(currentConfig)
) {

  throw new Error(
    "Prepare Next Experiment: strategy_config is missing."
  );

}


// =========================================================
// SIGNATURE FUNCTION
// =========================================================

function signature(config) {

  return JSON.stringify({

    strategy:
      config.strategy,

    parameters:
      config.parameters || {},

    stop_loss:
      config.risk?.stop_loss,

    take_profit:
      config.risk?.take_profit,

    lot_size:
      config.risk?.lot_size

  });

}


// =========================================================
// CHECK WHETHER CONFIG WAS ALREADY TESTED
// =========================================================

function alreadyTested(config) {

  const candidateSignature =
    signature(config);


  return history.some(
    record => {

      if (
        !record ||
        typeof record !== "object"
      ) {

        return false;

      }


      if (
        !record.strategy_config
      ) {

        return false;

      }


      return (
        signature(
          record.strategy_config
        ) ===
        candidateSignature
      );

    }
  );

}


// =========================================================
// DEEP COPY
// =========================================================

function clone(value) {

  return JSON.parse(
    JSON.stringify(value)
  );

}


// =========================================================
// NORMALIZE CONFIG
// =========================================================

function normalizeConfig(config) {

  const result =
    clone(config);


  result.data = {

    instrument:
      instrument,

    timeframe:
      timeframe

  };


  result.research = {

    research_run_id:
      researchRunId

  };


  result.capital = {

    starting_capital:
      startingCapital

  };


  return result;

}


// =========================================================
// CANDIDATE CONFIGURATIONS
// =========================================================

const candidates = [];


// =========================================================
// 1. CURRENT / CRITIC CONFIG
// =========================================================
//
// If Critic returned MODIFY, this may already contain
// a different strategy or different parameters.
//
// We try it first.
// =========================================================

const criticCandidate =
  normalizeConfig(
    currentConfig
  );

candidates.push(
  criticCandidate
);


// =========================================================
// STRATEGY-SPECIFIC REFINEMENT CANDIDATES
// =========================================================

const strategy =
  currentConfig.strategy;

const parameters =
  currentConfig.parameters || {};

const risk =
  currentConfig.risk || {};


// =========================================================
// EMA CROSSOVER
// =========================================================

if (
  strategy === "EMA_Crossover"
) {

  const fast =
    Number(
      parameters.fast_ema
    );

  const slow =
    Number(
      parameters.slow_ema
    );


  // Candidate A:
  // Slightly faster fast EMA

  if (
    fast > 5
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast - 1,

        slow_ema:
          slow

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Slightly slower fast EMA

  if (
    fast < 30 &&
    fast + 1 < slow
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast + 1,

        slow_ema:
          slow

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Increase slow EMA

  if (
    slow < 100
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast,

        slow_ema:
          slow + 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Decrease slow EMA

  if (
    slow > 20 &&
    slow - 5 > fast
  ) {

    candidates.push({

      strategy:
        "EMA_Crossover",

      parameters: {

        fast_ema:
          fast,

        slow_ema:
          slow - 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Change to RSI family

  candidates.push({

    strategy:
      "RSI_Mean_Reversion",

    parameters: {

      rsi_period:
        14,

      oversold:
        30,

      overbought:
        70

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Change to Supertrend

  candidates.push({

    strategy:
      "Supertrend",

    parameters: {

      atr_period:
        10,

      multiplier:
        3

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// RSI MEAN REVERSION
// =========================================================

if (
  strategy === "RSI_Mean_Reversion"
) {

  const period =
    Number(
      parameters.rsi_period
    );

  const oversold =
    Number(
      parameters.oversold
    );

  const overbought =
    Number(
      parameters.overbought
    );


  // Candidate A:
  // Shorter RSI period

  if (
    period > 5
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period - 1,

        oversold:
          oversold,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Longer RSI period

  if (
    period < 30
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period + 1,

        oversold:
          oversold,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Wider oversold threshold

  if (
    oversold > 20
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period,

        oversold:
          oversold - 5,

        overbought:
          overbought

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Lower overbought threshold

  if (
    overbought > 60
  ) {

    candidates.push({

      strategy:
        "RSI_Mean_Reversion",

      parameters: {

        rsi_period:
          period,

        oversold:
          oversold,

        overbought:
          overbought - 5

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Switch to EMA

  candidates.push({

    strategy:
      "EMA_Crossover",

    parameters: {

      fast_ema:
        10,

      slow_ema:
        30

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Switch to Supertrend

  candidates.push({

    strategy:
      "Supertrend",

    parameters: {

      atr_period:
        10,

      multiplier:
        3

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// SUPERTREND
// =========================================================

if (
  strategy === "Supertrend"
) {

  const atrPeriod =
    Number(
      parameters.atr_period
    );

  const multiplier =
    Number(
      parameters.multiplier
    );


  // Candidate A:
  // Lower ATR period

  if (
    atrPeriod > 5
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod - 1,

        multiplier:
          multiplier

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate B:
  // Higher ATR period

  if (
    atrPeriod < 30
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod + 1,

        multiplier:
          multiplier

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate C:
  // Lower multiplier

  if (
    multiplier > 1
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod,

        multiplier:
          Math.max(
            1,
            Number(
              (
                multiplier - 0.5
              ).toFixed(1)
            )
          )

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate D:
  // Higher multiplier

  if (
    multiplier < 5
  ) {

    candidates.push({

      strategy:
        "Supertrend",

      parameters: {

        atr_period:
          atrPeriod,

        multiplier:
          Math.min(
            5,
            Number(
              (
                multiplier + 0.5
              ).toFixed(1)
            )
          )

      },

      risk:
        clone(risk),

      data: {

        instrument:
          instrument,

        timeframe:
          timeframe

      },

      research: {

        research_run_id:
          researchRunId

      },

      capital: {

        starting_capital:
          startingCapital

      }

    });

  }


  // Candidate E:
  // Switch to EMA

  candidates.push({

    strategy:
      "EMA_Crossover",

    parameters: {

      fast_ema:
        10,

      slow_ema:
        30

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });


  // Candidate F:
  // Switch to RSI

  candidates.push({

    strategy:
      "RSI_Mean_Reversion",

    parameters: {

      rsi_period:
        14,

      oversold:
        30,

      overbought:
        70

    },

    risk:
      clone(risk),

    data: {

      instrument:
        instrument,

      timeframe:
        timeframe

    },

    research: {

      research_run_id:
        researchRunId

    },

    capital: {

      starting_capital:
        startingCapital

    }

  });

}


// =========================================================
// FIND FIRST UNUSED CANDIDATE
// =========================================================

let selectedConfig =
  null;


for (
  const candidate of candidates
) {

  const normalized =
    normalizeConfig(
      candidate
    );


  if (
    !alreadyTested(
      normalized
    )
  ) {

    selectedConfig =
      normalized;

    break;

  }

}


// =========================================================
// NO VALID CANDIDATE
// =========================================================

if (
  !selectedConfig
) {

  throw new Error(
    "Unable to create a new unique experiment configuration."
  );

}


// =========================================================
// FINAL OUTPUT
// =========================================================

return [{
  json: {

    decision:
      "MODIFY",

    retry_required:
      false,

    reason:
      "Prepared a new unique configuration for the next experiment.",

    research_run_id:
      researchRunId,

    instrument:
      instrument,

    timeframe:
      timeframe,

    starting_capital:
      startingCapital,

    experiment:
      nextExperiment,

    max_experiments:
      maxExperiments,

    strategy:
      selectedConfig.strategy,

    strategy_config:
      selectedConfig,

    history:
      history,

    fast_ema:
      selectedConfig.strategy === "EMA_Crossover"
        ? selectedConfig.parameters.fast_ema
        : null,

    slow_ema:
      selectedConfig.strategy === "EMA_Crossover"
        ? selectedConfig.parameters.slow_ema
        : null,

    rsi_period:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.rsi_period
        : null,

    oversold:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.oversold
        : null,

    overbought:
      selectedConfig.strategy === "RSI_Mean_Reversion"
        ? selectedConfig.parameters.overbought
        : null,

    atr_period:
      selectedConfig.strategy === "Supertrend"
        ? selectedConfig.parameters.atr_period
        : null,

    multiplier:
      selectedConfig.strategy === "Supertrend"
        ? selectedConfig.parameters.multiplier
        : null,

    stop_loss:
      selectedConfig.risk.stop_loss,

    take_profit:
      selectedConfig.risk.take_profit,

    lot_size:
      selectedConfig.risk.lot_size

  }
}];

const output = $json.output;

const backtest = $("HTTP Request").item.json;

const currentConfig =
  backtest.strategy_config || {};

const history =
  Array.isArray(backtest.history)
    ? backtest.history
    : [];


// =========================================================
// HELPERS
// =========================================================

function toNumber(value, fallback = null) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}


function cleanString(value, fallback = null) {
  if (value === undefined || value === null) {
    return fallback;
  }

  return String(value);
}


// =========================================================
// HEAT
// =========================================================
//
// Python is authoritative.
//
// The parser does NOT recalculate Heat when Python already
// supplied it.
//
// A fallback calculation is included only for compatibility
// with older executions that may not contain Heat fields.
// =========================================================

function deriveHeatFromMetrics(backtestData) {

  const returnPercent =
    toNumber(backtestData.return_percent);

  const profitFactor =
    toNumber(backtestData.profit_factor);

  const sharpe =
    toNumber(backtestData.sharpe_ratio);

  const drawdown =
    toNumber(backtestData.max_drawdown_percent);

  if (
    returnPercent === null ||
    profitFactor === null ||
    sharpe === null ||
    drawdown === null
  ) {
    return {
      heat_score: null,
      heat_label: null,
      heat_checks: null
    };
  }

  const checks = {
    positive_return:
      returnPercent > 0,

    profit_factor_above_1:
      profitFactor > 1,

    positive_sharpe:
      sharpe > 0,

    drawdown_better_than_10_percent:
      drawdown > -10
  };

  const score =
    Object.values(checks)
      .filter(Boolean)
      .length;

  let label = "COLD";

  if (score === 1) {
    label = "COOL";
  }
  else if (score === 2) {
    label = "WARM";
  }
  else if (score === 3) {
    label = "HOT";
  }
  else if (score === 4) {
    label = "VERY HOT";
  }

  return {
    heat_score: score,
    heat_label: label,
    heat_checks: checks
  };
}


function getCurrentHeat(data) {

  if (
    data.heat_score !== undefined &&
    data.heat_label !== undefined
  ) {

    return {
      heat_score:
        toNumber(data.heat_score),

      heat_label:
        cleanString(data.heat_label),

      heat_checks:
        data.heat_checks || null
    };

  }

  return deriveHeatFromMetrics(data);
}


const currentHeat =
  getCurrentHeat(backtest);


// =========================================================
// HISTORY HEAT NORMALIZATION
// =========================================================
//
// Older history entries may not contain Heat.
//
// New entries will always contain it.
// =========================================================

function normalizeHistoryEntry(entry) {

  if (
    entry &&
    entry.heat_score !== undefined &&
    entry.heat_label !== undefined
  ) {

    return {
      ...entry,

      heat_score:
        toNumber(entry.heat_score),

      heat_label:
        cleanString(entry.heat_label),

      heat_checks:
        entry.heat_checks || null
    };

  }

  const derived =
    deriveHeatFromMetrics(entry || {});

  return {
    ...entry,

    heat_score:
      derived.heat_score,

    heat_label:
      derived.heat_label,

    heat_checks:
      derived.heat_checks
  };
}


const normalizedHistory =
  history.map(
    normalizeHistoryEntry
  );


// =========================================================
// PREVIOUS HEAT
// =========================================================

let previousHeatScore = null;
let previousHeatLabel = null;

if (normalizedHistory.length > 0) {

  const previous =
    normalizedHistory[
      normalizedHistory.length - 1
    ];

  previousHeatScore =
    toNumber(previous.heat_score);

  previousHeatLabel =
    cleanString(previous.heat_label);
}


// =========================================================
// HEAT COMPARISON
// =========================================================

let heatChange = null;
let heatAssessment = "BASELINE";

if (
  previousHeatScore !== null &&
  currentHeat.heat_score !== null
) {

  heatChange =
    currentHeat.heat_score -
    previousHeatScore;

  if (heatChange > 0) {
    heatAssessment = "IMPROVED";
  }
  else if (heatChange < 0) {
    heatAssessment = "WORSENED";
  }
  else {
    heatAssessment = "UNCHANGED";
  }
}


// =========================================================
// RETRY HELPER
// =========================================================

function retry(
  reason,
  rejectedConfig = null
) {

  const previousRetryCount =
    Number(
      $json.retry_count || 0
    );

  return [{
    json: {

      decision:
        "RETRY",

      retry_required:
        true,

      retry_count:
        previousRetryCount + 1,

      retry_reason:
        reason,

      reason:
        reason,

      rejected_configuration:
        rejectedConfig,

      strategy:
        currentConfig.strategy ||
        backtest.strategy,

      strategy_config:
        currentConfig,

      instrument:
        currentConfig.data?.instrument ||
        backtest.instrument,

      timeframe:
        currentConfig.data?.timeframe ||
        backtest.timeframe,

      starting_capital:
        Number(
          currentConfig.capital?.starting_capital ||
          backtest.initial_capital ||
          backtest.starting_capital ||
          10000
        ),

      research_run_id:
        currentConfig.research?.research_run_id ||
        backtest.research_run_id,

      experiment:
        Number(
          backtest.experiment || 1
        ),

      max_experiments:
        Number(
          backtest.max_experiments || 5
        ),

      return_percent:
        Number(
          backtest.return_percent
        ),

      trades:
        Number(
          backtest.trades
        ),

      win_rate:
        Number(
          backtest.win_rate
        ),

      profit_factor:
        Number(
          backtest.profit_factor
        ),

      max_drawdown_percent:
        Number(
          backtest.max_drawdown_percent
        ),

      sharpe_ratio:
        Number(
          backtest.sharpe_ratio
        ),

      heat_score:
        currentHeat.heat_score,

      heat_label:
        currentHeat.heat_label,

      heat_checks:
        currentHeat.heat_checks,

      previous_heat_score:
        previousHeatScore,

      previous_heat_label:
        previousHeatLabel,

      heat_change:
        heatChange,

      heat_assessment:
        heatAssessment,

      history:
        normalizedHistory
    }
  }];
}


// =========================================================
// BASIC OUTPUT VALIDATION
// =========================================================

if (
  typeof output !== "string" ||
  output.trim() === ""
) {

  return retry(
    "Critic AI output was empty."
  );

}


// =========================================================
// EXTRACT DECISION
// =========================================================

let decision = null;

const decisionMatch =
  output.match(
    /"decision"\s*:\s*"(MODIFY|ACCEPT|RETRY)"/i
  );

if (decisionMatch) {

  decision =
    decisionMatch[1]
      .toUpperCase();

}

if (!decision) {

  const textDecision =
    output.match(
      /\b(MODIFY|ACCEPT|RETRY)\b/i
    );

  if (textDecision) {

    decision =
      textDecision[1]
        .toUpperCase();

  }
}


// =========================================================
// EXTRACT BALANCED JSON OBJECTS
// =========================================================

function extractJsonObjects(text) {

  const objects = [];

  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (
    let i = 0;
    i < text.length;
    i++
  ) {

    const char =
      text[i];

    if (escaped) {

      escaped = false;

      continue;

    }

    if (
      char === "\\" &&
      inString
    ) {

      escaped = true;

      continue;

    }

    if (char === '"') {

      inString =
        !inString;

      continue;

    }

    if (inString) {
      continue;
    }

    if (char === "{") {

      if (depth === 0) {
        start = i;
      }

      depth++;

    }

    else if (char === "}") {

      depth--;

      if (
        depth === 0 &&
        start !== -1
      ) {

        objects.push(
          text.substring(
            start,
            i + 1
          )
        );

        start = -1;

      }

    }

  }

  return objects;
}


const candidates =
  extractJsonObjects(output);

const parsedCandidates = [];


for (
  const candidate of candidates
) {

  try {

    const parsed =
      JSON.parse(candidate);

    if (
      parsed &&
      typeof parsed === "object" &&
      !Array.isArray(parsed)
    ) {

      parsedCandidates.push(
        parsed
      );

    }

  }

  catch (error) {

    // Ignore malformed candidates.

  }

}


// =========================================================
// FIND PARSED DECISION
// =========================================================

let parsed =
  parsedCandidates.find(
    candidate =>
      candidate.decision === decision
  );


if (!parsed) {

  parsed =
    parsedCandidates.find(
      candidate =>
        candidate.strategy_config
    );

}


// =========================================================
// HEAT ANALYSIS VALIDATION
// =========================================================
//
// This is the important new protection.
//
// The Critic must explicitly return heat_analysis.
// The parser verifies that its values agree with Python.
// =========================================================

function validateHeatAnalysis(
  candidate
) {

  const analysis =
    candidate?.heat_analysis;

  if (
    !analysis ||
    typeof analysis !== "object"
  ) {

    return {
      valid: false,
      reason:
        "Critic must provide heat_analysis explicitly."
    };

  }

  const candidateCurrentScore =
    analysis.current_heat_score === null ||
    analysis.current_heat_score === undefined
      ? null
      : Number(
          analysis.current_heat_score
        );

  const candidatePreviousScore =
    analysis.previous_heat_score === null ||
    analysis.previous_heat_score === undefined
      ? null
      : Number(
          analysis.previous_heat_score
        );

  const candidateChange =
    analysis.heat_change === null ||
    analysis.heat_change === undefined
      ? null
      : Number(
          analysis.heat_change
        );


  // Current score must match Python.

  if (
    candidateCurrentScore !==
    currentHeat.heat_score
  ) {

    return {
      valid: false,
      reason:
        "Critic heat_analysis current_heat_score does not match Python Heat Score."
    };

  }


  // Previous score must match history.

  if (
    candidatePreviousScore !==
    previousHeatScore
  ) {

    return {
      valid: false,
      reason:
        "Critic heat_analysis previous_heat_score does not match previous experiment Heat."
    };

  }


  // Validate score change.

  if (
    previousHeatScore !== null &&
    currentHeat.heat_score !== null
  ) {

    const expectedChange =
      currentHeat.heat_score -
      previousHeatScore;

    if (
      candidateChange !==
      expectedChange
    ) {

      return {
        valid: false,
        reason:
          "Critic heat_analysis heat_change is incorrect."
      };

    }

  }
  else {

    if (
      candidateChange !== null
    ) {

      return {
        valid: false,
        reason:
          "Critic heat_analysis heat_change must be null for the baseline experiment."
      };

    }

  }


  // Validate labels.

  if (
    cleanString(
      analysis.current_heat_label
    ) !==
    currentHeat.heat_label
  ) {

    return {
      valid: false,
      reason:
        "Critic current_heat_label does not match Python Heat."
    };

  }


  if (
    cleanString(
      analysis.previous_heat_label
    ) !==
    previousHeatLabel
  ) {

    return {
      valid: false,
      reason:
        "Critic previous_heat_label does not match history."
    };

  }


  // Validate assessment.

  if (
    cleanString(
      analysis.assessment
    ) !==
    heatAssessment
  ) {

    return {
      valid: false,
      reason:
        "Critic Heat assessment does not match the actual Heat change."
    };

  }


  return {
    valid: true
  };
}


// =========================================================
// REQUIRE HEAT ANALYSIS
// =========================================================

if (
  !parsed ||
  !parsed.heat_analysis
) {

  return retry(
    "Critic did not explicitly provide the required heat_analysis."
  );

}


const heatValidation =
  validateHeatAnalysis(
    parsed
  );


if (
  !heatValidation.valid
) {

  return retry(
    heatValidation.reason
  );

}


// =========================================================
// REQUIRE HEAT REFERENCE IN REASON
// =========================================================
//
// This prevents a technically correct heat_analysis object
// from being ignored in the actual reasoning.
// =========================================================

const reasonText =
  String(
    parsed.reason || ""
  );

if (
  !/\bheat\b/i.test(reasonText)
) {

  return retry(
    "Critic reason must explicitly discuss Heat and how the Heat change influenced the decision."
  );

}


// =========================================================
// ACCEPT
// =========================================================

if (
  decision === "ACCEPT"
) {

  const reason =
    parsed.reason ||
    "Critic accepted the current strategy.";

  const updatedHistory =
    normalizedHistory.slice();


  const currentExperiment = {

    experiment:
      Number(
        backtest.experiment || 1
      ),

    strategy:
      currentConfig.strategy ||
      backtest.strategy,

    strategy_config:
      currentConfig,

    return_percent:
      Number(
        backtest.return_percent
      ),

    trades:
      Number(
        backtest.trades
      ),

    win_rate:
      Number(
        backtest.win_rate
      ),

    profit_factor:
      Number(
        backtest.profit_factor
      ),

    max_drawdown_percent:
      Number(
        backtest.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        backtest.sharpe_ratio
      ),

    heat_score:
      currentHeat.heat_score,

    heat_label:
      currentHeat.heat_label,

    heat_checks:
      currentHeat.heat_checks
  };


  const alreadyStored =
    updatedHistory.some(
      exp =>
        Number(exp.experiment) ===
        Number(
          backtest.experiment
        )
    );


  if (
    !alreadyStored
  ) {

    updatedHistory.push(
      currentExperiment
    );

  }


  return [{
    json: {

      decision:
        "ACCEPT",

      retry_required:
        false,

      reason,

      heat_analysis:
        parsed.heat_analysis,

      strategy:
        currentConfig.strategy ||
        backtest.strategy,

      strategy_config:
        currentConfig,

      instrument:
        currentConfig.data?.instrument ||
        backtest.instrument,

      timeframe:
        currentConfig.data?.timeframe ||
        backtest.timeframe,

      starting_capital:
        Number(
          currentConfig.capital?.starting_capital ||
          backtest.initial_capital ||
          backtest.starting_capital ||
          10000
        ),

      research_run_id:
        currentConfig.research?.research_run_id ||
        backtest.research_run_id,

      experiment:
        Number(
          backtest.experiment || 1
        ),

      max_experiments:
        Number(
          backtest.max_experiments || 5
        ),

      return_percent:
        Number(
          backtest.return_percent
        ),

      trades:
        Number(
          backtest.trades
        ),

      win_rate:
        Number(
          backtest.win_rate
        ),

      profit_factor:
        Number(
          backtest.profit_factor
        ),

      max_drawdown_percent:
        Number(
          backtest.max_drawdown_percent
        ),

      sharpe_ratio:
        Number(
          backtest.sharpe_ratio
        ),

      heat_score:
        currentHeat.heat_score,

      heat_label:
        currentHeat.heat_label,

      heat_checks:
        currentHeat.heat_checks,

      previous_heat_score:
        previousHeatScore,

      previous_heat_label:
        previousHeatLabel,

      heat_change:
        heatChange,

      heat_assessment:
        heatAssessment,

      history:
        updatedHistory

    }
  }];

}


// =========================================================
// MODIFY VALIDATION
// =========================================================

if (
  decision !== "MODIFY"
) {

  return retry(
    "Critic did not provide a valid MODIFY or ACCEPT decision."
  );

}


if (
  !parsed ||
  !parsed.strategy_config
) {

  return retry(
    "Critic proposed MODIFY but no strategy_config was found."
  );

}


const proposedConfig =
  parsed.strategy_config;


// =========================================================
// STRATEGY
// =========================================================

const strategy =
  proposedConfig.strategy;


if (
  strategy !== "EMA_Crossover" &&
  strategy !== "RSI_Mean_Reversion" &&
  strategy !== "Supertrend"
) {

  return retry(
    "Critic proposed an unsupported strategy. Supported strategies are EMA_Crossover, RSI_Mean_Reversion, and Supertrend.",
    proposedConfig
  );

}


// =========================================================
// PARAMETERS
// =========================================================

const parameters =
  proposedConfig.parameters;


if (
  !parameters ||
  typeof parameters !== "object" ||
  Array.isArray(parameters)
) {

  return retry(
    "Critic strategy_config is missing valid parameters.",
    proposedConfig
  );

}


// =========================================================
// EMA
// =========================================================

if (
  strategy === "EMA_Crossover"
) {

  const fast =
    Number(
      parameters.fast_ema
    );

  const slow =
    Number(
      parameters.slow_ema
    );


  if (
    !Number.isInteger(fast) ||
    fast < 5 ||
    fast > 30
  ) {

    return retry(
      "Critic proposed invalid fast_ema. Allowed range is 5-30.",
      proposedConfig
    );

  }


  if (
    !Number.isInteger(slow) ||
    slow < 20 ||
    slow > 100
  ) {

    return retry(
      "Critic proposed invalid slow_ema. Allowed range is 20-100.",
      proposedConfig
    );

  }


  if (
    slow <= fast
  ) {

    return retry(
      "Critic proposed slow_ema that is not greater than fast_ema.",
      proposedConfig
    );

  }

}


// =========================================================
// RSI
// =========================================================

if (
  strategy === "RSI_Mean_Reversion"
) {

  const rsiPeriod =
    Number(
      parameters.rsi_period
    );

  const oversold =
    Number(
      parameters.oversold
    );

  const overbought =
    Number(
      parameters.overbought
    );


  if (
    !Number.isInteger(rsiPeriod) ||
    rsiPeriod < 5 ||
    rsiPeriod > 30
  ) {

    return retry(
      "Critic proposed invalid rsi_period. Allowed range is 5-30.",
      proposedConfig
    );

  }


  if (
    !Number.isFinite(oversold) ||
    oversold < 20 ||
    oversold > 40
  ) {

    return retry(
      "Critic proposed invalid oversold. Allowed range is 20-40.",
      proposedConfig
    );

  }


  if (
    !Number.isFinite(overbought) ||
    overbought < 60 ||
    overbought > 80
  ) {

    return retry(
      "Critic proposed invalid overbought. Allowed range is 60-80.",
      proposedConfig
    );

  }


  if (
    oversold >= overbought
  ) {

    return retry(
      "Critic proposed oversold that is not less than overbought.",
      proposedConfig
    );

  }

}


// =========================================================
// SUPERTREND
// =========================================================

if (
  strategy === "Supertrend"
) {

  const atrPeriod =
    Number(
      parameters.atr_period
    );

  const multiplier =
    Number(
      parameters.multiplier
    );


  if (
    !Number.isInteger(atrPeriod) ||
    atrPeriod < 5 ||
    atrPeriod > 30
  ) {

    return retry(
      "Critic proposed invalid atr_period. Allowed range is 5-30.",
      proposedConfig
    );

  }


  if (
    !Number.isFinite(multiplier) ||
    multiplier < 1 ||
    multiplier > 5
  ) {

    return retry(
      "Critic proposed invalid multiplier. Allowed range is 1.0-5.0.",
      proposedConfig
    );

  }

}


// =========================================================
// RISK
// =========================================================

const risk =
  proposedConfig.risk;


if (
  !risk ||
  typeof risk !== "object" ||
  Array.isArray(risk)
) {

  return retry(
    "Critic strategy_config is missing a valid risk object.",
    proposedConfig
  );

}


// =========================================================
// STOP LOSS
// =========================================================

let stopLoss =
  risk.stop_loss;

if (
  stopLoss !== null &&
  stopLoss !== undefined
) {

  stopLoss =
    Number(
      stopLoss
    );


  if (
    !Number.isFinite(stopLoss) ||
    stopLoss <= 0
  ) {

    return retry(
      "Critic proposed invalid stop_loss.",
      proposedConfig
    );

  }

}
else {

  stopLoss = null;

}


// =========================================================
// TAKE PROFIT
// =========================================================

let takeProfit =
  risk.take_profit;

if (
  takeProfit !== null &&
  takeProfit !== undefined
) {

  takeProfit =
    Number(
      takeProfit
    );


  if (
    !Number.isFinite(takeProfit) ||
    takeProfit <= 0
  ) {

    return retry(
      "Critic proposed invalid take_profit.",
      proposedConfig
    );

  }

}
else {

  takeProfit = null;

}


// =========================================================
// CAPITAL
// =========================================================

const startingCapital =
  Number(
    currentConfig.capital?.starting_capital ||
    backtest.initial_capital ||
    backtest.starting_capital ||
    10000
  );


// =========================================================
// LOT SIZE
// =========================================================

let lotSize =
  Number(
    risk.lot_size
  );


if (
  !Number.isFinite(lotSize) ||
  lotSize <= 0
) {

  return retry(
    "Critic proposed invalid lot_size.",
    proposedConfig
  );

}


if (
  lotSize > startingCapital
) {

  return retry(
    "Critic proposed lot_size greater than starting capital.",
    proposedConfig
  );

}


// =========================================================
// IMMUTABLE CONTEXT
// =========================================================

const instrument =
  currentConfig.data?.instrument ||
  backtest.instrument;

const timeframe =
  currentConfig.data?.timeframe ||
  backtest.timeframe;

const researchRunId =
  currentConfig.research?.research_run_id ||
  backtest.research_run_id;


// =========================================================
// IMMUTABLE VALIDATION
// =========================================================

if (
  proposedConfig.data?.instrument !== undefined &&
  proposedConfig.data.instrument !== instrument
) {

  return retry(
    "Critic attempted to change the instrument.",
    proposedConfig
  );

}


if (
  proposedConfig.data?.timeframe !== undefined &&
  proposedConfig.data.timeframe !== timeframe
) {

  return retry(
    "Critic attempted to change the timeframe.",
    proposedConfig
  );

}


if (
  proposedConfig.capital?.starting_capital !== undefined &&
  Number(
    proposedConfig.capital.starting_capital
  ) !== startingCapital
) {

  return retry(
    "Critic attempted to change starting capital.",
    proposedConfig
  );

}


if (
  proposedConfig.research?.research_run_id !== undefined &&
  proposedConfig.research.research_run_id !== researchRunId
) {

  return retry(
    "Critic attempted to change research run ID.",
    proposedConfig
  );

}


// =========================================================
// NORMALIZED NEXT CONFIGURATION
// =========================================================

const nextConfig = {

  strategy,

  parameters,

  risk: {

    stop_loss:
      stopLoss,

    take_profit:
      takeProfit,

    lot_size:
      lotSize

  },

  data: {

    instrument,

    timeframe

  },

  capital: {

    starting_capital:
      startingCapital

  },

  research: {

    research_run_id:
      researchRunId

  }

};


// =========================================================
// CONFIGURATION SIGNATURE
// =========================================================

function configurationSignature(
  config
) {

  return JSON.stringify({

    strategy:
      config.strategy,

    parameters:
      config.parameters || {},

    risk: {

      stop_loss:
        config.risk?.stop_loss ??
        null,

      take_profit:
        config.risk?.take_profit ??
        null,

      lot_size:
        config.risk?.lot_size ??
        null

    }

  });

}


const proposedSignature =
  configurationSignature(
    nextConfig
  );


// =========================================================
// DUPLICATE CHECK
// =========================================================

const alreadyTested =
  normalizedHistory.some(
    experiment => {

      if (
        !experiment.strategy_config
      ) {

        return false;

      }

      return (
        configurationSignature(
          experiment.strategy_config
        ) ===
        proposedSignature
      );

    }
  );


if (
  alreadyTested
) {

  return retry(
    "The complete proposed configuration has already been tested. Change at least one strategy or risk parameter.",
    nextConfig
  );

}


// =========================================================
// STORE CURRENT EXPERIMENT
// =========================================================

const updatedHistory =
  normalizedHistory.slice();


const currentExperiment = {

  experiment:
    Number(
      backtest.experiment || 1
    ),

  strategy:
    currentConfig.strategy ||
    backtest.strategy,

  strategy_config:
    currentConfig,

  return_percent:
    Number(
      backtest.return_percent
    ),

  trades:
    Number(
      backtest.trades
    ),

  win_rate:
    Number(
      backtest.win_rate
    ),

  profit_factor:
    Number(
      backtest.profit_factor
    ),

  max_drawdown_percent:
    Number(
      backtest.max_drawdown_percent
    ),

  sharpe_ratio:
    Number(
      backtest.sharpe_ratio
    ),

  heat_score:
    currentHeat.heat_score,

  heat_label:
    currentHeat.heat_label,

  heat_checks:
    currentHeat.heat_checks
};


const alreadyStored =
  updatedHistory.some(
    exp =>
      Number(exp.experiment) ===
      Number(
        backtest.experiment
      )
  );


if (
  !alreadyStored
) {

  updatedHistory.push(
    currentExperiment
  );

}


// =========================================================
// RETURN NEXT EXPERIMENT
// =========================================================

return [{
  json: {

    decision:
      "MODIFY",

    retry_required:
      false,

    reason:
      parsed.reason ||
      "Critic proposed a new configuration.",

    heat_analysis:
      parsed.heat_analysis,

    strategy:
      nextConfig.strategy,

    strategy_config:
      nextConfig,

    instrument:
      nextConfig.data.instrument,

    timeframe:
      nextConfig.data.timeframe,

    starting_capital:
      startingCapital,

    research_run_id:
      nextConfig.research.research_run_id,

    experiment:
      Number(
        backtest.experiment || 1
      ),

    max_experiments:
      Number(
        backtest.max_experiments || 5
      ),

    return_percent:
      Number(
        backtest.return_percent
      ),

    trades:
      Number(
        backtest.trades
      ),

    win_rate:
      Number(
        backtest.win_rate
      ),

    profit_factor:
      Number(
        backtest.profit_factor
      ),

    max_drawdown_percent:
      Number(
        backtest.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        backtest.sharpe_ratio
      ),

    heat_score:
      currentHeat.heat_score,

    heat_label:
      currentHeat.heat_label,

    heat_checks:
      currentHeat.heat_checks,

    previous_heat_score:
      previousHeatScore,

    previous_heat_label:
      previousHeatLabel,

    heat_change:
      heatChange,

    heat_assessment:
      heatAssessment,

    history:
      updatedHistory

  }
}];

const history = Array.isArray($json.history)
  ? $json.history
  : [];

if (history.length === 0) {
  throw new Error(
    "No experiment history available."
  );
}


// ---------------------------------------------------------
// Select best experiment using only performance metrics.
// No strategy-specific parameters are used here.
// ---------------------------------------------------------

let best = history[0];

for (const experiment of history) {

  const currentReturn =
    Number(experiment.return_percent);

  const bestReturn =
    Number(best.return_percent);

  // 1. Highest return
  if (currentReturn > bestReturn) {

    best = experiment;
    continue;
  }

  if (currentReturn !== bestReturn) {
    continue;
  }


  // 2. Highest profit factor
  const currentPF =
    Number(experiment.profit_factor);

  const bestPF =
    Number(best.profit_factor);

  if (currentPF > bestPF) {

    best = experiment;
    continue;
  }

  if (currentPF !== bestPF) {
    continue;
  }


  // 3. Highest Sharpe ratio
  const currentSharpe =
    Number(experiment.sharpe_ratio);

  const bestSharpe =
    Number(best.sharpe_ratio);

  if (currentSharpe > bestSharpe) {

    best = experiment;
    continue;
  }

  if (currentSharpe !== bestSharpe) {
    continue;
  }


  // 4. Better maximum drawdown
  // Example:
  // -3% is better than -5%
  const currentDrawdown =
    Number(
      experiment.max_drawdown_percent
    );

  const bestDrawdown =
    Number(
      best.max_drawdown_percent
    );

  if (
    currentDrawdown >
    bestDrawdown
  ) {

    best = experiment;
  }
}


// ---------------------------------------------------------
// Validate selected experiment
// ---------------------------------------------------------

if (
  best.experiment === undefined ||
  best.experiment === null
) {
  throw new Error(
    "Select Best Strategy could not identify a valid experiment."
  );
}


const strategyConfig =
  best.strategy_config;

if (
  !strategyConfig ||
  typeof strategyConfig !== "object" ||
  Array.isArray(strategyConfig)
) {
  throw new Error(
    "Selected experiment does not contain a valid strategy_config."
  );
}


// ---------------------------------------------------------
// Return selected experiment
// ---------------------------------------------------------

return [{
  json: {

    best_experiment:
      Number(
        best.experiment
      ),

    strategy:
      strategyConfig.strategy ||
      best.strategy,

    strategy_config:
      strategyConfig,

    return_percent:
      Number(
        best.return_percent
      ),

    trades:
      Number(
        best.trades
      ),

    win_rate:
      Number(
        best.win_rate
      ),

    profit_factor:
      Number(
        best.profit_factor
      ),

    max_drawdown_percent:
      Number(
        best.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        best.sharpe_ratio
      ),

    history:
      history
  }
}];

const validatorOutput = $json.output;

if (
  typeof validatorOutput !== "string" ||
  validatorOutput.trim() === ""
) {
  throw new Error(
    "Validator AI output is empty or invalid."
  );
}

let text = validatorOutput
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

let aiValidation;

try {
  aiValidation = JSON.parse(text);
} catch (firstError) {
  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");

  if (
    firstBrace === -1 ||
    lastBrace <= firstBrace
  ) {
    throw new Error(
      "Validator AI did not return valid JSON."
    );
  }

  try {
    aiValidation = JSON.parse(
      text.substring(
        firstBrace,
        lastBrace + 1
      )
    );
  } catch (secondError) {
    throw new Error(
      "Validator AI returned malformed JSON."
    );
  }
}


// ---------------------------------------------------------
// Deterministic validator is authoritative
// ---------------------------------------------------------

const deterministic =
  $("Deterministic Validator").item.json;

const strategyConfig =
  deterministic.strategy_config || {};

const parameters =
  strategyConfig.parameters || {};

const risk =
  strategyConfig.risk || {};

const data =
  strategyConfig.data || {};

const capital =
  strategyConfig.capital || {};

const research =
  strategyConfig.research || {};


// ---------------------------------------------------------
// Extract strategy parameters from nested config
// ---------------------------------------------------------

const fastEma =
  parameters.fast_ema !== undefined &&
  parameters.fast_ema !== null
    ? Number(parameters.fast_ema)
    : null;

const slowEma =
  parameters.slow_ema !== undefined &&
  parameters.slow_ema !== null
    ? Number(parameters.slow_ema)
    : null;

const lotSize =
  risk.lot_size !== undefined &&
  risk.lot_size !== null
    ? Number(risk.lot_size)
    : null;


// ---------------------------------------------------------
// Return final validation state
// ---------------------------------------------------------

return [{
  json: {

    validation:
      deterministic.validation,

    validation_reason:
      aiValidation.reason ||
      deterministic.validation_reason,

    validation_checks:
      deterministic.validation_checks,

    minimum_trades_required:
      deterministic.minimum_trades_required,

    best_experiment:
      Number(
        deterministic.best_experiment
      ),

    strategy:
      strategyConfig.strategy ||
      deterministic.strategy,

    strategy_config:
      strategyConfig,

    parameters:
      parameters,

    risk:
      risk,

    data:
      data,

    capital:
      capital,

    research:
      research,

    fast_ema:
      fastEma,

    slow_ema:
      slowEma,

    lot_size:
      lotSize,

    return_percent:
      Number(
        deterministic.return_percent
      ),

    trades:
      Number(
        deterministic.trades
      ),

    win_rate:
      Number(
        deterministic.win_rate
      ),

    profit_factor:
      Number(
        deterministic.profit_factor
      ),

    max_drawdown_percent:
      Number(
        deterministic.max_drawdown_percent
      ),

    sharpe_ratio:
      Number(
        deterministic.sharpe_ratio
      ),

    history:
      deterministic.history || []
  }
}];

// ============================================================
// QUANTFORGE — FINAL RESEARCH REPORT
// ============================================================
// Purpose:
//   Build the final human-readable research report from the
//   deterministic workflow output.
//
// Important:
//   Heat is NOT calculated here.
//   Heat comes from the Python backtest engine and is only
//   displayed here.
// ============================================================

const data = $json;

// ------------------------------------------------------------
// HELPERS
// ------------------------------------------------------------

function safe(value, fallback = "N/A") {
    return value === undefined || value === null
        ? fallback
        : value;
}

function formatNumber(value, decimals = 2) {
    const n = Number(value);

    if (!Number.isFinite(n)) {
        return "N/A";
    }

    return n.toFixed(decimals);
}

function formatPercent(value) {
    const n = Number(value);

    if (!Number.isFinite(n)) {
        return "N/A";
    }

    return `${n.toFixed(2)}%`;
}

function passFail(value) {
    return value ? "PASS" : "FAIL";
}

function heatText(experiment) {
    const score = safe(experiment.heat_score, "N/A");
    const label = safe(experiment.heat_label, "N/A");

    return `${score}/4 — ${label}`;
}

function formatParameters(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const parameters = config.parameters;

    if (!parameters || typeof parameters !== "object") {
        return "N/A";
    }

    const parts = [];

    for (const [key, value] of Object.entries(parameters)) {
        parts.push(`${key}: ${value}`);
    }

    return parts.join(", ");
}

function formatRisk(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const risk = config.risk;

    if (!risk || typeof risk !== "object") {
        return "N/A";
    }

    return [
        `stop_loss: ${safe(risk.stop_loss)}`,
        `take_profit: ${safe(risk.take_profit)}`,
        `lot_size: ${safe(risk.lot_size)}`
    ].join(", ");
}

function formatData(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const dataConfig = config.data;

    if (!dataConfig || typeof dataConfig !== "object") {
        return "N/A";
    }

    return [
        `instrument: ${safe(dataConfig.instrument)}`,
        `timeframe: ${safe(dataConfig.timeframe)}`
    ].join(", ");
}

function formatCapital(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const capital = config.capital;

    if (!capital || typeof capital !== "object") {
        return "N/A";
    }

    return `starting_capital: ${safe(capital.starting_capital)}`;
}

function formatResearch(config) {

    if (!config || typeof config !== "object") {
        return "N/A";
    }

    const research = config.research;

    if (!research || typeof research !== "object") {
        return "N/A";
    }

    return `research_run_id: ${safe(research.research_run_id)}`;
}


// ------------------------------------------------------------
// EXTRACT CORE DATA
// ------------------------------------------------------------

const strategyConfig = data.strategy_config || {};

const strategy =
    data.strategy ||
    strategyConfig.strategy ||
    "N/A";

const history =
    Array.isArray(data.history)
        ? data.history
        : [];

const bestExperiment = data.best_experiment;

const validation =
    data.validation ||
    "UNKNOWN";

const validationChecks =
    data.validation_checks &&
    typeof data.validation_checks === "object"
        ? data.validation_checks
        : {};

const validationReason =
    data.validation_reason ||
    "No validator explanation provided.";

const researchObjective =
    data.research_objective ||
    "Not provided.";

const instrument =
    data.instrument ||
    strategyConfig?.data?.instrument ||
    "N/A";

const timeframe =
    data.timeframe ||
    strategyConfig?.data?.timeframe ||
    "N/A";


// ------------------------------------------------------------
// FIND BEST EXPERIMENT FROM HISTORY
// ------------------------------------------------------------

let bestExperimentData = null;

if (history.length > 0) {

    bestExperimentData = history.find(
        experiment =>
            Number(experiment.experiment) === Number(bestExperiment)
    );

    // Fallback if exact experiment number wasn't found.
    if (!bestExperimentData) {

        bestExperimentData = history[history.length - 1];
    }
}


// ------------------------------------------------------------
// FINAL METRICS
// ------------------------------------------------------------

const finalReturn =
    bestExperimentData?.return_percent ??
    data.return_percent;

const finalTrades =
    bestExperimentData?.trades ??
    data.trades;

const finalWinRate =
    bestExperimentData?.win_rate ??
    data.win_rate;

const finalProfitFactor =
    bestExperimentData?.profit_factor ??
    data.profit_factor;

const finalDrawdown =
    bestExperimentData?.max_drawdown_percent ??
    data.max_drawdown_percent;

const finalSharpe =
    bestExperimentData?.sharpe_ratio ??
    data.sharpe_ratio;

const finalHeatScore =
    bestExperimentData?.heat_score ??
    data.heat_score;

const finalHeatLabel =
    bestExperimentData?.heat_label ??
    data.heat_label;

const finalHeatChecks =
    bestExperimentData?.heat_checks ??
    data.heat_checks ??
    {};


// ------------------------------------------------------------
// BUILD REPORT
// ------------------------------------------------------------

let report = "";

report += "QUANTFORGE RESEARCH REPORT\n";
report += "===========================\n\n";

report += `Research Objective:\n`;
report += `${researchObjective}\n\n`;

report += `Instrument: ${instrument}\n`;
report += `Timeframe: ${timeframe}\n`;
report += `Strategy: ${strategy}\n`;
report += `Experiments Conducted: ${history.length}\n\n`;


// ============================================================
// EXPERIMENT RESULTS
// ============================================================

report += "EXPERIMENT RESULTS\n";
report += "------------------\n\n";

for (let index = 0; index < history.length; index++) {

    const experiment = history[index];

    if (!experiment || typeof experiment !== "object") {
        continue;
    }

    const config =
        experiment.strategy_config &&
        typeof experiment.strategy_config === "object"
            ? experiment.strategy_config
            : {};

    report += `Experiment ${safe(experiment.experiment, index + 1)}\n`;

    report += `Strategy: ${safe(
        config.strategy || experiment.strategy,
        "N/A"
    )}\n`;

    report += `Parameters: ${formatParameters(config)}\n`;

    report += `Risk: ${formatRisk(config)}\n`;

    report += `Data: ${formatData(config)}\n`;

    report += `Capital: ${formatCapital(config)}\n`;

    report += `Research: ${formatResearch(config)}\n`;

    report += `Return: ${formatPercent(experiment.return_percent)}\n`;

    report += `Trades: ${safe(experiment.trades)}\n`;

    report += `Win Rate: ${formatPercent(experiment.win_rate)}\n`;

    report += `Profit Factor: ${formatNumber(
        experiment.profit_factor
    )}\n`;

    report += `Maximum Drawdown: ${formatPercent(
        experiment.max_drawdown_percent
    )}\n`;

    report += `Sharpe Ratio: ${formatNumber(
        experiment.sharpe_ratio
    )}\n`;

    // --------------------------------------------------------
    // HEAT
    // --------------------------------------------------------

    report += `Heat Score: ${heatText(experiment)}\n`;

    const heatChecks =
        experiment.heat_checks &&
        typeof experiment.heat_checks === "object"
            ? experiment.heat_checks
            : {};

    report += "Heat Checks:\n";

    report += `  Positive Return: ${passFail(
        heatChecks.positive_return
    )}\n`;

    report += `  Profit Factor > 1: ${passFail(
        heatChecks.profit_factor_above_1
    )}\n`;

    report += `  Sharpe Ratio > 0: ${passFail(
        heatChecks.positive_sharpe
    )}\n`;

    report += `  Drawdown > -10%: ${passFail(
        heatChecks.drawdown_better_than_10_percent
    )}\n`;

    report += "\n";
}


// ============================================================
// HEAT PROGRESSION
// ============================================================

report += "HEAT PROGRESSION\n";
report += "----------------\n\n";

if (history.length === 0) {

    report += "No experiment history available.\n\n";

} else {

    for (let index = 0; index < history.length; index++) {

        const experiment = history[index];

        if (!experiment || typeof experiment !== "object") {
            continue;
        }

        report +=
            `Experiment ${safe(experiment.experiment, index + 1)}: ` +
            `${heatText(experiment)}\n`;
    }

    report += "\n";

    for (let index = 1; index < history.length; index++) {

        const previous = history[index - 1];
        const current = history[index];

        const previousScore = Number(previous.heat_score);
        const currentScore = Number(current.heat_score);

        if (
            Number.isFinite(previousScore) &&
            Number.isFinite(currentScore)
        ) {

            const change = currentScore - previousScore;

            const sign =
                change > 0
                    ? "+"
                    : "";

            report +=
                `Experiment ${previous.experiment} → ` +
                `Experiment ${current.experiment}: ` +
                `${sign}${change} Heat points\n`;
        }
    }

    report += "\n";
}


// ============================================================
// BEST STRATEGY
// ============================================================

report += "BEST STRATEGY\n";
report += "-------------\n";

report += `Experiment: ${safe(bestExperiment)}\n`;

report += `Strategy: ${strategy}\n`;

report += `Parameters: ${formatParameters(strategyConfig)}\n`;

report += `Risk: ${formatRisk(strategyConfig)}\n`;

report += `Data: ${formatData(strategyConfig)}\n`;

report += `Capital: ${formatCapital(strategyConfig)}\n`;

report += `Research: ${formatResearch(strategyConfig)}\n`;

report += `Return: ${formatPercent(finalReturn)}\n`;

report += `Trades: ${safe(finalTrades)}\n`;

report += `Win Rate: ${formatPercent(finalWinRate)}\n`;

report += `Profit Factor: ${formatNumber(finalProfitFactor)}\n`;

report += `Maximum Drawdown: ${formatPercent(finalDrawdown)}\n`;

report += `Sharpe Ratio: ${formatNumber(finalSharpe)}\n`;

report += `Heat Score: ${safe(finalHeatScore)}/4\n`;

report += `Heat Label: ${safe(finalHeatLabel)}\n`;

report += "\n";

report += "Heat Checks:\n";

report += `Positive Return: ${passFail(
    finalHeatChecks.positive_return
)}\n`;

report += `Profit Factor > 1: ${passFail(
    finalHeatChecks.profit_factor_above_1
)}\n`;

report += `Sharpe Ratio > 0: ${passFail(
    finalHeatChecks.positive_sharpe
)}\n`;

report += `Maximum Drawdown > -10%: ${passFail(
    finalHeatChecks.drawdown_better_than_10_percent
)}\n`;

report += "\n";


// ============================================================
// VALIDATION
// ============================================================

report += "VALIDATION\n";
report += "----------\n";

report += `Validation: ${validation}\n\n`;

report += "Validation Checks:\n";

report += `Positive Return: ${passFail(
    validationChecks.positive_return
)}\n`;

report += `Profit Factor > 1: ${passFail(
    validationChecks.profit_factor_above_1
)}\n`;

report += `Sharpe Ratio > 0: ${passFail(
    validationChecks.positive_sharpe
)}\n`;

report += `Maximum Drawdown > -10%: ${passFail(
    validationChecks.drawdown_better_than_10_percent
)}\n`;

report += `Trade Count >= 100: ${passFail(
    validationChecks.reasonable_trade_count
)}\n`;

report += "\n";

report += "Validator Explanation:\n";
report += `${validationReason}\n\n`;


// ============================================================
// CONCLUSION
// ============================================================

report += "CONCLUSION\n";
report += "----------\n";

report +=
    `Experiment ${safe(bestExperiment)} was selected as ` +
    `the best candidate from the experiments conducted. `;

report +=
    `The selected configuration produced a return of ` +
    `${formatPercent(finalReturn)}, ` +
    `profit factor of ${formatNumber(finalProfitFactor)}, ` +
    `Sharpe ratio of ${formatNumber(finalSharpe)}, ` +
    `and maximum drawdown of ${formatPercent(finalDrawdown)}. `;

report +=
    `Its deterministic Heat Score was ` +
    `${safe(finalHeatScore)}/4 (${safe(finalHeatLabel)}). `;

report +=
    `The deterministic validation stage marked the strategy ` +
    `as ${validation}.`;


// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
    {
        json: {
            ...data,

            report,

            // Explicit reporting fields
            report_instrument: instrument,
            report_timeframe: timeframe,
            report_strategy: strategy,

            final_heat_score: finalHeatScore,
            final_heat_label: finalHeatLabel,
            final_heat_checks: finalHeatChecks,

            report_best_experiment: bestExperiment,

            // Filename convention:
            // <instrument>_<timeframe>_<strategy>.pdf
            report_filename:
                `${String(instrument).trim()}_` +
                `${String(timeframe).trim()}_` +
                `${String(strategy).trim()}.pdf`
        }
    }
];

const best = $json;

const minTrades = 100;

const checks = {
  positive_return: Number(best.return_percent) > 0,
  profit_factor_above_1: Number(best.profit_factor) > 1,
  positive_sharpe: Number(best.sharpe_ratio) > 0,
  drawdown_better_than_10_percent: Number(best.max_drawdown_percent) > -10,
  reasonable_trade_count: Number(best.trades) >= minTrades
};

const passed = Object.values(checks).every(Boolean);

const failedChecks = Object.entries(checks)
  .filter(([key, value]) => !value)
  .map(([key]) => key);

let validationReason;

if (passed) {
  validationReason =
    "The strategy satisfies all deterministic validation criteria.";
} else {
  validationReason =
    "The strategy failed the following validation criteria: " +
    failedChecks.join(", ") + ".";
}

return [{
  json: {
    ...best,

    validation: passed ? "PASS" : "FAIL",

    validation_checks: checks,

    validation_reason: validationReason,

    minimum_trades_required: minTrades
  }
}];

const config = $json.strategy_config;

if (!config || typeof config !== "object") {
  throw new Error("Researcher did not provide a valid strategy_config.");
}

if (!config.strategy) {
  throw new Error("strategy_config.strategy is missing.");
}

if (!config.parameters || typeof config.parameters !== "object") {
  throw new Error("strategy_config.parameters is missing or invalid.");
}

if (!config.risk || typeof config.risk !== "object") {
  throw new Error("strategy_config.risk is missing or invalid.");
}

if (!config.data || typeof config.data !== "object") {
  throw new Error("strategy_config.data is missing or invalid.");
}

if (!config.capital || typeof config.capital !== "object") {
  throw new Error("strategy_config.capital is missing or invalid.");
}

if (!config.research || typeof config.research !== "object") {
  throw new Error("strategy_config.research is missing or invalid.");
}


// ---------------------------------------------------------
// Supported strategy families
// ---------------------------------------------------------

const supportedStrategies = [
  "EMA_Crossover",
  "RSI_Mean_Reversion",
  "Supertrend"
];

if (!supportedStrategies.includes(config.strategy)) {
  throw new Error(
    `Unsupported strategy family: ${config.strategy}`
  );
}


// ---------------------------------------------------------
// Preserve complete configuration
// ---------------------------------------------------------

const strategyConfig = {
  strategy: config.strategy,
  parameters: config.parameters,
  risk: config.risk,
  data: config.data,
  research: config.research,
  capital: config.capital
};


// ---------------------------------------------------------
// Compatibility fields
// ---------------------------------------------------------
// These are kept because the current HTTP Request and some
// existing n8n nodes still reference them.

const parameters = strategyConfig.parameters;
const risk = strategyConfig.risk;

return [
  {
    json: {
      ...$json,

      strategy_config: strategyConfig,

      strategy: strategyConfig.strategy,

      fast_ema:
        parameters.fast_ema !== undefined
          ? Number(parameters.fast_ema)
          : null,

      slow_ema:
        parameters.slow_ema !== undefined
          ? Number(parameters.slow_ema)
          : null,

      rsi_period:
        parameters.rsi_period !== undefined
          ? Number(parameters.rsi_period)
          : null,

      oversold:
        parameters.oversold !== undefined
          ? Number(parameters.oversold)
          : null,

      overbought:
        parameters.overbought !== undefined
          ? Number(parameters.overbought)
          : null,

      atr_period:
        parameters.atr_period !== undefined
          ? Number(parameters.atr_period)
          : null,

      multiplier:
        parameters.multiplier !== undefined
          ? Number(parameters.multiplier)
          : null,

      stop_loss:
        risk.stop_loss !== undefined
          ? Number(risk.stop_loss)
          : null,

      take_profit:
        risk.take_profit !== undefined
          ? Number(risk.take_profit)
          : null,

      lot_size:
        risk.lot_size !== undefined
          ? Number(risk.lot_size)
          : null
    }
  }
];

// =========================================================
// QuantForge - Researcher Parser
// =========================================================
// Purpose:
// 1. Parse Researcher AI output
// 2. Validate exactly ONE strategy family
// 3. Validate strategy-specific parameters
// 4. Validate common risk parameters
// 5. Preserve immutable research context
// 6. Reject malformed AI output
// 7. Support retry loop back to Researcher AI
// 8. Produce one canonical strategy_config
// =========================================================


// =========================================================
// ORIGINAL RESEARCH CONTEXT
// =========================================================

let originalInput = {};

try {

  originalInput =
    $("Edit Fields").first().json || {};

} catch (error) {

  originalInput = {};

}


// =========================================================
// RESEARCHER AI OUTPUT
// =========================================================

const output =
  $json.output;


// =========================================================
// EXTRACT POSSIBLE STRATEGY CONFIG
// =========================================================

let initialResearcherConfig = {};

if (
  $json.strategy_config &&
  typeof $json.strategy_config === "object" &&
  !Array.isArray($json.strategy_config)
) {

  initialResearcherConfig =
    $json.strategy_config;

}


// ---------------------------------------------------------
// Nested context from Researcher AI
// ---------------------------------------------------------

const initialData =
  initialResearcherConfig.data &&
  typeof initialResearcherConfig.data === "object"
    ? initialResearcherConfig.data
    : {};

const initialResearch =
  initialResearcherConfig.research &&
  typeof initialResearcherConfig.research === "object"
    ? initialResearcherConfig.research
    : {};

const initialCapital =
  initialResearcherConfig.capital &&
  typeof initialResearcherConfig.capital === "object"
    ? initialResearcherConfig.capital
    : {};


// =========================================================
// IMMUTABLE RESEARCH CONTEXT
// =========================================================

const researchObjective =
  originalInput.research_objective ||
  $json.research_objective ||
  "";

const researchRunId =
  originalInput.research_run_id ||
  $json.research_run_id ||
  initialResearch.research_run_id;

const instrument =
  originalInput.instrument ||
  $json.instrument ||
  initialData.instrument;

const timeframe =
  originalInput.timeframe ||
  $json.timeframe ||
  initialData.timeframe;

const startingCapital =
  Number(
    originalInput.starting_capital ??
    $json.starting_capital ??
    initialCapital.starting_capital ??
    10000
  );

const experiment =
  Number(
    originalInput.experiment ??
    $json.experiment ??
    1
  );

const maxExperiments =
  Number(
    originalInput.max_experiments ??
    $json.max_experiments ??
    5
  );


// =========================================================
// HISTORY
// =========================================================

const history =
  Array.isArray($json.history)
    ? $json.history
    : [];


// =========================================================
// RETRY HELPER
// =========================================================

function retry(reason) {

  return [{
    json: {

      retry_required:
        true,

      retry_reason:
        reason,

      research_objective:
        researchObjective,

      research_run_id:
        researchRunId,

      instrument:
        instrument,

      timeframe:
        timeframe,

      starting_capital:
        startingCapital,

      experiment:
        experiment,

      max_experiments:
        maxExperiments,

      history:
        history

    }
  }];

}


// =========================================================
// BASIC CONTEXT VALIDATION
// =========================================================

if (!instrument) {

  return retry(
    "Instrument is missing."
  );

}

if (!timeframe) {

  return retry(
    "Timeframe is missing."
  );

}

if (
  !Number.isFinite(startingCapital) ||
  startingCapital <= 0
) {

  return retry(
    "Starting capital must be greater than zero."
  );

}

if (
  !Number.isInteger(experiment) ||
  experiment < 1
) {

  return retry(
    "Experiment number is invalid."
  );

}

if (
  !Number.isInteger(maxExperiments) ||
  maxExperiments < 1
) {

  return retry(
    "max_experiments is invalid."
  );

}


// =========================================================
// PARSE RESEARCHER OUTPUT
// =========================================================

let parsed = null;


try {

  // -------------------------------------------------------
  // Case 1: output is already an object
  // -------------------------------------------------------

  if (
    output &&
    typeof output === "object" &&
    !Array.isArray(output)
  ) {

    parsed =
      output;

  }

  // -------------------------------------------------------
  // Case 2: output is a JSON string
  // -------------------------------------------------------

  else {

    let text =
      String(output || "").trim();


    if (!text) {

      return retry(
        "Researcher returned empty output."
      );

    }


    // Remove Markdown fences

    text =
      text
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();


    // First attempt: entire string

    try {

      parsed =
        JSON.parse(text);

    } catch (directError) {

      // ---------------------------------------------------
      // Extract first JSON object
      // ---------------------------------------------------

      const start =
        text.indexOf("{");

      const end =
        text.lastIndexOf("}");


      if (
        start !== -1 &&
        end !== -1 &&
        end > start
      ) {

        parsed =
          JSON.parse(
            text.substring(
              start,
              end + 1
            )
          );

      }

    }

  }

} catch (error) {

  return retry(
    "Researcher output was not valid JSON."
  );

}


// =========================================================
// PARSED OBJECT VALIDATION
// =========================================================

if (
  !parsed ||
  typeof parsed !== "object" ||
  Array.isArray(parsed)
) {

  return retry(
    "Researcher did not return a valid JSON object."
  );

}


// =========================================================
// GET STRATEGY CONFIG
// =========================================================

let proposedConfig =
  parsed.strategy_config;


// ---------------------------------------------------------
// Fallback:
// Some outputs may put strategy directly at root.
// ---------------------------------------------------------

if (
  !proposedConfig ||
  typeof proposedConfig !== "object" ||
  Array.isArray(proposedConfig)
) {

  proposedConfig = {

    strategy:
      parsed.strategy,

    parameters:
      parsed.parameters,

    risk:
      parsed.risk,

    data:
      parsed.data,

    research:
      parsed.research,

    capital:
      parsed.capital

  };

}


// =========================================================
// STRATEGY
// =========================================================

let strategy =
  proposedConfig.strategy;


// =========================================================
// SUPPORTED STRATEGIES
// =========================================================

const supportedStrategies = [

  "EMA_Crossover",

  "RSI_Mean_Reversion",

  "Supertrend"

];


// =========================================================
// DETECT MULTIPLE STRATEGIES
// =========================================================

if (
  typeof strategy === "string"
) {

  const strategyText =
    strategy.trim();


  const detectedStrategies =
    supportedStrategies.filter(
      candidate =>
        strategyText.includes(candidate)
    );


  // -------------------------------------------------------
  // More than one strategy detected
  // -------------------------------------------------------

  if (
    detectedStrategies.length > 1
  ) {

    return retry(
      "Researcher returned multiple strategy families: " +
      detectedStrategies.join(", ") +
      ". Select exactly ONE strategy family."
    );

  }

}


// =========================================================
// NORMALIZE COMMON STRATEGY ALIASES
// =========================================================

if (
  strategy === "EMA Crossover"
) {

  strategy =
    "EMA_Crossover";

}

if (
  strategy === "RSI Mean Reversion"
) {

  strategy =
    "RSI_Mean_Reversion";

}

if (
  strategy === "RSI_Mean-Reversion"
) {

  strategy =
    "RSI_Mean_Reversion";

}


// =========================================================
// FINAL STRATEGY VALIDATION
// =========================================================

if (
  typeof strategy !== "string" ||
  !supportedStrategies.includes(strategy)
) {

  return retry(
    "Unsupported strategy family. Select exactly one of EMA_Crossover, RSI_Mean_Reversion, or Supertrend."
  );

}


// =========================================================
// PARAMETERS
// =========================================================

let parameters =
  proposedConfig.parameters;


if (
  !parameters ||
  typeof parameters !== "object" ||
  Array.isArray(parameters)
) {

  parameters = {};

}


// =========================================================
// RISK
// =========================================================

let risk =
  proposedConfig.risk;


if (
  !risk ||
  typeof risk !== "object" ||
  Array.isArray(risk)
) {

  risk = {};

}


// =========================================================
// EMA CROSSOVER
// =========================================================

if (
  strategy === "EMA_Crossover"
) {

  const fastEma =
    Number(
      parameters.fast_ema ??
      parsed.fast_ema
    );

  const slowEma =
    Number(
      parameters.slow_ema ??
      parsed.slow_ema
    );


  // -------------------------------------------------------
  // fast EMA
  // -------------------------------------------------------

  if (
    !Number.isInteger(fastEma) ||
    fastEma < 5 ||
    fastEma > 30
  ) {

    return retry(
      "Invalid fast_ema. It must be an integer between 5 and 30."
    );

  }


  // -------------------------------------------------------
  // slow EMA
  // -------------------------------------------------------

  if (
    !Number.isInteger(slowEma) ||
    slowEma < 20 ||
    slowEma > 100
  ) {

    return retry(
      "Invalid slow_ema. It must be an integer between 20 and 100."
    );

  }


  // -------------------------------------------------------
  // EMA ordering
  // -------------------------------------------------------

  if (
    slowEma <= fastEma
  ) {

    return retry(
      "slow_ema must be greater than fast_ema."
    );

  }


  // -------------------------------------------------------
  // IMPORTANT:
  // Only EMA parameters survive.
  // Any RSI/Supertrend parameters are discarded.
  // -------------------------------------------------------

  parameters = {

    fast_ema:
      fastEma,

    slow_ema:
      slowEma

  };

}


// =========================================================
// RSI MEAN REVERSION
// =========================================================

if (
  strategy === "RSI_Mean_Reversion"
) {

  const rsiPeriod =
    Number(
      parameters.rsi_period ??
      parsed.rsi_period
    );

  const oversold =
    Number(
      parameters.oversold ??
      parsed.oversold
    );

  const overbought =
    Number(
      parameters.overbought ??
      parsed.overbought
    );


  // -------------------------------------------------------
  // RSI period
  // -------------------------------------------------------

  if (
    !Number.isInteger(rsiPeriod) ||
    rsiPeriod < 5 ||
    rsiPeriod > 30
  ) {

    return retry(
      "Invalid rsi_period. It must be an integer between 5 and 30."
    );

  }


  // -------------------------------------------------------
  // Oversold
  // -------------------------------------------------------

  if (
    !Number.isFinite(oversold) ||
    oversold < 20 ||
    oversold > 40
  ) {

    return retry(
      "Invalid oversold value. It must be between 20 and 40."
    );

  }


  // -------------------------------------------------------
  // Overbought
  // -------------------------------------------------------

  if (
    !Number.isFinite(overbought) ||
    overbought < 60 ||
    overbought > 80
  ) {

    return retry(
      "Invalid overbought value. It must be between 60 and 80."
    );

  }


  // -------------------------------------------------------
  // RSI relationship
  // -------------------------------------------------------

  if (
    oversold >= overbought
  ) {

    return retry(
      "oversold must be less than overbought."
    );

  }


  // -------------------------------------------------------
  // Only RSI parameters survive
  // -------------------------------------------------------

  parameters = {

    rsi_period:
      rsiPeriod,

    oversold:
      oversold,

    overbought:
      overbought

  };

}


// =========================================================
// SUPERTREND
// =========================================================

if (
  strategy === "Supertrend"
) {

  const atrPeriod =
    Number(
      parameters.atr_period ??
      parsed.atr_period
    );

  const multiplier =
    Number(
      parameters.multiplier ??
      parsed.multiplier
    );


  // -------------------------------------------------------
  // ATR period
  // -------------------------------------------------------

  if (
    !Number.isInteger(atrPeriod) ||
    atrPeriod < 5 ||
    atrPeriod > 30
  ) {

    return retry(
      "Invalid atr_period. It must be an integer between 5 and 30."
    );

  }


  // -------------------------------------------------------
  // Multiplier
  // -------------------------------------------------------

  if (
    !Number.isFinite(multiplier) ||
    multiplier < 1 ||
    multiplier > 5
  ) {

    return retry(
      "Invalid multiplier. It must be between 1 and 5."
    );

  }


  // -------------------------------------------------------
  // Only Supertrend parameters survive
  // -------------------------------------------------------

  parameters = {

    atr_period:
      atrPeriod,

    multiplier:
      multiplier

  };

}


// =========================================================
// COMMON RISK PARAMETERS
// =========================================================

const stopLoss =
  Number(
    risk.stop_loss ??
    parsed.stop_loss
  );

const takeProfit =
  Number(
    risk.take_profit ??
    parsed.take_profit
  );

const lotSize =
  Number(
    risk.lot_size ??
    parsed.lot_size
  );


// =========================================================
// STOP LOSS
// =========================================================

if (
  !Number.isFinite(stopLoss) ||
  stopLoss <= 0
) {

  return retry(
    "stop_loss must be a positive number."
  );

}


// =========================================================
// TAKE PROFIT
// =========================================================

if (
  !Number.isFinite(takeProfit) ||
  takeProfit <= 0
) {

  return retry(
    "take_profit must be a positive number."
  );

}


// =========================================================
// LOT SIZE
// =========================================================

if (
  !Number.isFinite(lotSize) ||
  lotSize <= 0
) {

  return retry(
    "lot_size must be greater than zero."
  );

}


if (
  lotSize > startingCapital
) {

  return retry(
    "lot_size cannot be greater than starting capital."
  );

}


// =========================================================
// CANONICAL STRATEGY CONFIG
// =========================================================

const strategyConfig = {

  strategy:
    strategy,

  parameters:
    parameters,

  risk: {

    stop_loss:
      stopLoss,

    take_profit:
      takeProfit,

    lot_size:
      lotSize

  },

  data: {

    instrument:
      instrument,

    timeframe:
      timeframe

  },

  research: {

    research_run_id:
      researchRunId

  },

  capital: {

    starting_capital:
      startingCapital

  }

};


// =========================================================
// DUPLICATE CONFIGURATION CHECK
// =========================================================

function createSignature(config) {

  return JSON.stringify({

    strategy:
      config.strategy,

    parameters:
      config.parameters,

    stop_loss:
      config.risk?.stop_loss,

    take_profit:
      config.risk?.take_profit,

    lot_size:
      config.risk?.lot_size

  });

}


const newSignature =
  createSignature(
    strategyConfig
  );


const duplicate =
  history.some(
    experimentRecord => {

      if (
        !experimentRecord ||
        typeof experimentRecord !== "object"
      ) {

        return false;

      }


      const previousConfig =
        experimentRecord.strategy_config;


      if (
        !previousConfig ||
        typeof previousConfig !== "object"
      ) {

        return false;

      }


      return (
        createSignature(
          previousConfig
        ) ===
        newSignature
      );

    }
  );


if (
  duplicate
) {

  return retry(
    "Researcher proposed a strategy configuration that already exists in experiment history. Propose a different configuration."
  );

}


// =========================================================
// FINAL OUTPUT
// =========================================================

return [{
  json: {

    retry_required:
      false,

    retry_reason:
      null,

    research_objective:
      researchObjective,

    research_run_id:
      researchRunId,

    instrument:
      instrument,

    timeframe:
      timeframe,

    starting_capital:
      startingCapital,

    experiment:
      experiment,

    max_experiments:
      maxExperiments,

    strategy:
      strategy,

    strategy_config:
      strategyConfig,


    // -----------------------------------------------------
    // Compatibility fields
    // -----------------------------------------------------

    fast_ema:
      strategy === "EMA_Crossover"
        ? parameters.fast_ema
        : null,

    slow_ema:
      strategy === "EMA_Crossover"
        ? parameters.slow_ema
        : null,


    rsi_period:
      strategy === "RSI_Mean_Reversion"
        ? parameters.rsi_period
        : null,

    oversold:
      strategy === "RSI_Mean_Reversion"
        ? parameters.oversold
        : null,

    overbought:
      strategy === "RSI_Mean_Reversion"
        ? parameters.overbought
        : null,


    atr_period:
      strategy === "Supertrend"
        ? parameters.atr_period
        : null,

    multiplier:
      strategy === "Supertrend"
        ? parameters.multiplier
        : null,


    stop_loss:
      stopLoss,

    take_profit:
      takeProfit,

    lot_size:
      lotSize,

    history:
      history

  }
}];

const current = $json;

const strategyConfig =
  current.strategy_config || {};

const history =
  Array.isArray(current.history)
    ? current.history
    : [];

const dataConfig =
  strategyConfig.data || {};

const capitalConfig =
  strategyConfig.capital || {};

const researchConfig =
  strategyConfig.research || {};

return [{
  json: {

    // ---------------------------------------------------
    // Decision from Critic
    // ---------------------------------------------------

    decision:
      current.decision,

    reason:
      current.reason,

    // ---------------------------------------------------
    // Research state
    // ---------------------------------------------------

    research_objective:
      current.research_objective,

    research_run_id:
      current.research_run_id ||
      researchConfig.research_run_id,

    instrument:
      current.instrument ||
      dataConfig.instrument,

    timeframe:
      current.timeframe ||
      dataConfig.timeframe,

    starting_capital:
      Number(
        current.starting_capital ||
        capitalConfig.starting_capital ||
        10000
      ),

    experiment:
      Number(
        current.experiment || 1
      ),

    max_experiments:
      Number(
        current.max_experiments || 5
      ),

    // ---------------------------------------------------
    // Strategy configuration
    // ---------------------------------------------------

    strategy:
      strategyConfig.strategy ||
      current.strategy,

    strategy_config:
      strategyConfig,

    // ---------------------------------------------------
    // Compatibility fields
    // ---------------------------------------------------

    fast_ema:
      Number(
        strategyConfig.parameters?.fast_ema ??
        current.fast_ema ??
        0
      ),

    slow_ema:
      Number(
        strategyConfig.parameters?.slow_ema ??
        current.slow_ema ??
        0
      ),

    lot_size:
      strategyConfig.risk?.lot_size !== null &&
      strategyConfig.risk?.lot_size !== undefined
        ? Number(
            strategyConfig.risk.lot_size
          )
        : null,

    // ---------------------------------------------------
    // Experiment history
    // ---------------------------------------------------

    history:
      history
  }
}];

// ============================================================
// QUANTFORGE — PREPARE PDF PAYLOAD
// ============================================================

const payload = {
    ...$json
};

// ------------------------------------------------------------
// BASIC VALIDATION
// ------------------------------------------------------------

if (!payload.strategy_config) {
    throw new Error(
        "PDF payload error: strategy_config is missing."
    );
}

if (!Array.isArray(payload.history)) {
    throw new Error(
        "PDF payload error: history is missing or is not an array."
    );
}

if (payload.best_experiment === undefined) {
    throw new Error(
        "PDF payload error: best_experiment is missing."
    );
}

if (!payload.validation) {
    throw new Error(
        "PDF payload error: validation result is missing."
    );
}

// ------------------------------------------------------------
// VERIFY HEAT EXISTS
// ------------------------------------------------------------

for (const experiment of payload.history) {

    if (!experiment || typeof experiment !== "object") {
        continue;
    }

    if (
        experiment.heat_score === undefined ||
        experiment.heat_label === undefined
    ) {
        throw new Error(
            `PDF payload error: Heat data missing for experiment ${
                experiment.experiment ?? "unknown"
            }.`
        );
    }
}

// ------------------------------------------------------------
// METADATA
// ------------------------------------------------------------

const strategyConfig =
    payload.strategy_config || {};

const dataConfig =
    strategyConfig.data || {};

const instrument =
    payload.instrument ||
    dataConfig.instrument;

const timeframe =
    payload.timeframe ||
    dataConfig.timeframe;

const strategy =
    payload.strategy ||
    strategyConfig.strategy;

if (!instrument) {
    throw new Error(
        "PDF payload error: instrument is missing."
    );
}

if (!timeframe) {
    throw new Error(
        "PDF payload error: timeframe is missing."
    );
}

if (!strategy) {
    throw new Error(
        "PDF payload error: strategy is missing."
    );
}

// ------------------------------------------------------------
// REPORT METADATA
// ------------------------------------------------------------

payload.report_instrument = instrument;
payload.report_timeframe = timeframe;
payload.report_strategy = strategy;

payload.report_filename =
    `${String(instrument).trim()}_` +
    `${String(timeframe).trim()}_` +
    `${String(strategy).trim()}.pdf`;

// ------------------------------------------------------------
// RETURN NORMAL JSON
// ------------------------------------------------------------

return [
    {
        json: payload
    }
];

// ============================================================
// QUANTFORGE — PDF RESULT PARSER
// ============================================================

const stdout = $json.stdout;

if (!stdout) {
    throw new Error(
        "PDF generation returned no output."
    );
}

let result;

try {
    result = JSON.parse(stdout.trim());
} catch (error) {
    throw new Error(
        "Could not parse report_generator.py output.\n\n" +
        stdout
    );
}

if (!result.report_path) {
    throw new Error(
        "PDF generator did not return report_path."
    );
}

return [
    {
        json: {
            pdf_generated: true,

            report_path: result.report_path,
            report_filename: result.report_filename,

            instrument: result.instrument,
            timeframe: result.timeframe,
            strategy: result.strategy,

            best_experiment: result.best_experiment,
            experiments: result.experiments,

            heat_score: result.heat_score,
            heat_label: result.heat_label,

            trades_used_for_charts:
                result.trades_used_for_charts
        }
    }
];
